# PTX kernel and Python wrapper for fp16 matrix multiplication on A100 (sm_80)

PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry matmul_fp16(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 N
)
{
    // pointers
    .reg .u64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u64 %addr_a, %addr_b, %addr_c;
    .reg .u64 %tmp1, %tmp2, %tmp3;

    // thread / block indices
    .reg .u32 %tid_x, %tid_y, %ctaid_x, %ctaid_y;

    // matrix indices and loop counter
    .reg .u32 %i, %j, %k;

    // data registers
    .reg .f16 %a_val, %b_val;
    .reg .f32 %a_f32, %b_f32, %sum;

    // predicates
    .reg .pred %p_exit_i, %p_exit_j, %p_done_k;

    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    ld.param.u64 %a_ptr, [A];
    ld.param.u64 %b_ptr, [B];
    ld.param.u64 %c_ptr, [C];
    ld.param.u32 %N,    [N];

    // Thread / block IDs
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %tid_y,   %tid.y;
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ctaid_y, %ctaid.y;

    // Global row (i) and column (j) for this thread
    mad.lo.u32 %i, %ctaid_x, 16, %tid_x;   // i = blockIdx.x * 16 + threadIdx.x
    mad.lo.u32 %j, %ctaid_y, 16, %tid_y;   // j = blockIdx.y * 16 + threadIdx.y

    // Bounds check – exit if out‑of‑range
    setp.ge.u32 %p_exit_i, %i, %N;
    @%p_exit_i bra DONE;
    setp.ge.u32 %p_exit_j, %j, %N;
    @%p_exit_j bra DONE;

    // -----------------------------------------------------------------
    // Compute C[i,j] = Σ_k A[i,k] * B[k,j]
    // -----------------------------------------------------------------
    mov.f32 %sum, 0f00000000;          // sum = 0.0f
    mov.u32 %k, 0;                     // k = 0

LOOP_K:
    setp.ge.u32 %p_done_k, %k, %N;     // if (k >= N) break
    @%p_done_k bra END_LOOP_K;

    // Load A[i,k] (half)
    mul.lo.u64 %tmp1, %i, %N;          // i * N
    add.u64 %tmp1, %tmp1, %k;          // i*N + k
    mul.wide.u32 %tmp1, %tmp1, 2;      // *sizeof(half)
    add.u64 %addr_a, %a_ptr, %tmp1;
    ld.global.f16 %a_val, [%addr_a];

    // Load B[k,j] (half)
    mul.lo.u64 %tmp2, %k, %N;          // k * N
    add.u64 %tmp2, %tmp2, %j;          // k*N + j
    mul.wide.u32 %tmp2, %tmp2, 2;
    add.u64 %addr_b, %b_ptr, %tmp2;
    ld.global.f16 %b_val, [%addr_b];

    // Convert to fp32 and accumulate
    cvt.f32.f16 %a_f32, %a_val;
    cvt.f32.f16 %b_f32, %b_val;
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;   // sum += a_f32 * b_f32

    // k++
    add.u32 %k, %k, 1;
    bra LOOP_K;

END_LOOP_K:
    // Convert final sum back to fp16
    cvt.rn.f16.f32 %a_val, %sum;

    // Store C[i,j]
    mul.lo.u64 %tmp3, %i, %N;          // i * N
    add.u64 %tmp3, %tmp3, %j;          // i*N + j
    mul.wide.u32 %tmp3, %tmp3, 2;      // *sizeof(half)
    add.u64 %addr_c, %c_ptr, %tmp3;
    st.global.f16 [%addr_c], %a_val;

DONE:
    ret;
}
'''

class ModelNew:
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B on fp16 tensors using a custom PTX kernel.
    """
    def __init__(self):
        # Load the PTX module (ptx_harness provides ptx_load)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A, B):
        """
        Execute the kernel.

        Args:
            A (torch.Tensor): (N, N) fp16 matrix.
            B (torch.Tensor): (N, N) fp16 matrix.

        Returns:
            torch.Tensor: (N, N) fp16 result matrix.
        """
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        N = A.shape[0]
        C = torch.empty_like(A, dtype=torch.float16)

        # Grid/block configuration (16x16 threads per block)
        grid = ((N + 15) // 16, (N + 15) // 16, 1)
        block = (16, 16, 1)

        # Arguments: raw device pointers and matrix dimension
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr(), N]

        # Launch the kernel (ptx_harness provides ptx_launch)
        ptx_launch(self.module, "matmul_fp16", grid, block, args)

        return C
